import { Archive, Calendar, Download, ExternalLink, FileText, MoreHorizontal, Plus, Upload, X } from 'lucide-react'
import { useCallback, useEffect, useState } from 'react'
import { AdminDetailModal } from '../../components/admin/AdminDetailModal'
import { CompanyLogo } from '../../components/admin/CompanyLogo'
import { adminRepository } from '../../repositories'
import type { CollaboratorRecord, RedComercialProspectDetailRecord, RedComercialProspectPanelRecord, RedComercialProspectStatus, RedComercialSpecialistMeetingOutcome, RedComercialSpecialistRequestRecord, RepresentedCompanyRecord, RepresentedCompanyServiceRecord } from '../../types/admin'
import { isRedComercialAdmin } from '../red-comercial-utils'
import { getOpportunityFinancialCue, getOpportunityPresentation } from '../opportunity-status'
import { getProspectStatusPresentation } from '../prospect-status'
import { useAdminAuth } from '../useAdminAuth'

type PanelProps = {
  prospect: RedComercialProspectDetailRecord
  opportunityId?: string
  onClose: () => void
  onEdit?: () => void
  onActivity?: () => void
  onArchive?: () => void
  onSchedule?: () => void
  onChanged?: () => void
}

const statuses: Array<[RedComercialProspectStatus, string]> = [
  ['to_contact', 'Por contactar'], ['contacted_no_response', 'Contactado - sin respuesta'], ['responded', 'Respondio'],
  ['follow_up', 'En seguimiento'], ['interested', 'Interesado'], ['meeting_scheduled', 'Reunion agendada'],
  ['agreed', 'Acordado'], ['not_interested', 'No interesado'], ['archived', 'Archivado'],
]

const canCreateOpportunityForProspect = (prospect: RedComercialProspectDetailRecord) =>
  !prospect.is_archived && !['archived', 'not_interested'].includes(prospect.status)

const statusTone: Record<string, string> = {
  to_contact: 'bg-stone-100 text-stone-700', contacted_no_response: 'bg-amber-50 text-amber-800', responded: 'bg-sky-50 text-sky-800',
  follow_up: 'bg-blue-50 text-blue-800', interested: 'bg-emerald-50 text-emerald-800', meeting_scheduled: 'bg-violet-50 text-violet-800',
  agreed: 'bg-[#e7f0ea] text-[#235b3e]', not_interested: 'bg-rose-50 text-rose-800', archived: 'bg-slate-100 text-slate-600',
}

function labelForStatus(status: string) { return statuses.find(([value]) => value === status)?.[1] ?? status }
function person(value: string | null | undefined) { return value?.trim().split(/\s+/).map((part) => `${part[0]?.toUpperCase() ?? ''}${part.slice(1).toLowerCase()}`).join(' ') || 'Sin definir' }
function date(value: string | null | undefined) { return value ? new Intl.DateTimeFormat('es-CL', { dateStyle: 'short' }).format(new Date(value)) : 'Sin definir' }
function dateTime(value: string | null | undefined) { return value ? new Intl.DateTimeFormat('es-CL', { dateStyle: 'short', timeStyle: 'short' }).format(new Date(value)) : 'Sin definir' }
function money(value: number | null, currency: string) { return value == null ? 'Por definir' : new Intl.NumberFormat('es-CL', { style: 'currency', currency, maximumFractionDigits: 0 }).format(value) }

function StatusBadge({ status }: { status: string }) {
  const presentation = getProspectStatusPresentation(status)
  return <span className={`inline-flex h-6 max-w-full items-center rounded-full border px-2 text-[10.5px] font-semibold leading-none ${presentation.backgroundClass} ${presentation.borderClass} ${presentation.textClass}`}>{presentation.label}</span>
}

function PanelSection({ title, action, children }: { title: string; action?: React.ReactNode; children: React.ReactNode }) {
  return <section className="border-b border-[#eee8dd] py-2 last:border-b-0"><div className="mb-1.5 flex items-center justify-between gap-2"><h3 className="text-[12.5px] font-semibold text-[#17202d]">{title}</h3>{action}</div>{children}</section>
}

function compensationText(opportunity: NonNullable<RedComercialProspectPanelRecord['opportunities']>[number]) {
  if (!opportunity.attributed_collaborator_id || !opportunity.collaborator_compensation_type) return 'Sin definir'
  if (opportunity.collaborator_compensation_type === 'fixed_amount') return money(opportunity.collaborator_compensation_amount, opportunity.currency)
  return opportunity.collaborator_compensation_rate == null ? 'Sin definir' : `${opportunity.collaborator_compensation_rate}%`
}

function OpportunityFinancialBadge({ kind, value }: { kind: 'payment' | 'commission'; value: string }) {
  const presentation = getOpportunityPresentation(kind, value)
  return <span className={`inline-flex min-h-6 items-center rounded-full border px-2 text-[10.5px] font-semibold ${presentation.className}`}>{presentation.label}</span>
}

function ServicePlaybookModal({ service, onClose }: { service: RepresentedCompanyServiceRecord; onClose: () => void }) {
  const blocks: Array<[string, string | null]> = [
    ['Problema que resuelve', service.problem_statement], ['Cliente ideal', service.ideal_customer],
    ['Decisores', service.decision_makers], ['Señales de oportunidad', service.opportunity_signals],
    ['Preguntas de descubrimiento', service.discovery_questions], ['Información mínima', service.required_information],
    ['Pitch sugerido', service.suggested_pitch], ['Cuándo derivar', service.handoff_guidance], ['Restricciones', service.restrictions],
  ]
  return <AdminDetailModal title={`Playbook · ${service.name}`} onClose={onClose}><div className="grid gap-3 text-[12px]"><div className="flex flex-wrap items-center gap-2"><span className="rounded-full bg-[#e7f0ea] px-2 py-1 text-[10px] font-semibold text-[#235b3e]">Prioridad {service.priority}</span>{service.category && <span className="text-[11px] text-slate-500">{service.category}</span>}</div>{service.short_description && <p className="text-slate-700">{service.short_description}</p>}{blocks.filter(([, value]) => value).map(([label, value]) => <section key={label} className="border-t border-[#eee8dd] pt-2"><h3 className="text-[11px] font-semibold text-[#17202d]">{label}</h3><p className="mt-1 whitespace-pre-line text-[11.5px] leading-5 text-slate-600">{value}</p></section>)}<footer className="flex justify-end border-t border-[#eee8dd] pt-3"><button type="button" onClick={onClose} className="rounded border border-[#c9c1b4] px-3 py-2 text-[11px] font-semibold">Cerrar</button></footer></div></AdminDetailModal>
}

function ReadOnlyOpportunity({ opportunity, attributedName, isAttributedUser, onOpenPlaybook }: { opportunity: NonNullable<RedComercialProspectPanelRecord['opportunities']>[number]; attributedName: string | null; isAttributedUser: boolean; onOpenPlaybook?: () => void }) {
  const cue = getOpportunityFinancialCue(opportunity.payment_status, opportunity.commission_status)
  const ownParticipation = Boolean(opportunity.attributed_collaborator_id && isAttributedUser)
  return <div data-readonly="true" className="grid gap-2 text-[12px]">
    <div className="grid gap-1.5 rounded-md border border-[#eee8dd] bg-[#fbfaf7] p-2">
      <div className="flex items-center justify-between gap-2"><span className="text-[10px] font-bold uppercase tracking-[0.08em] text-slate-500">Estado cliente</span><OpportunityFinancialBadge kind="payment" value={opportunity.payment_status} /></div>
      <div className="flex items-center justify-between gap-2"><span className="text-[10px] font-bold uppercase tracking-[0.08em] text-slate-500">{ownParticipation ? 'Mi participacion' : 'Participacion del colaborador'}</span><OpportunityFinancialBadge kind="commission" value={opportunity.commission_status} /></div>
      {opportunity.payment_status === 'paid' && ['to_validate', 'generated', 'pending_payment'].includes(opportunity.commission_status) && <p className="rounded border border-amber-100 bg-amber-50 px-2 py-1.5 text-[11px] font-semibold text-amber-800">Cliente pago · Tu participacion esta pendiente</p>}
    </div>
    <div className="grid text-[12px]">
      <div className="grid min-h-[28px] grid-cols-[118px_minmax(0,1fr)] items-center gap-2 border-b border-[#f1ece3]"><span className="text-[10.5px] font-semibold text-slate-500">Control actual</span><span className="text-[11.5px] text-[#17202d]">{getOpportunityPresentation('control', opportunity.control_mode).label}</span></div>
      <div className="grid min-h-[28px] grid-cols-[118px_minmax(0,1fr)] items-center gap-2 border-b border-[#f1ece3]"><span className="text-[10.5px] font-semibold text-slate-500">Resultado</span><span className="text-[11.5px] text-[#17202d]">{getOpportunityPresentation('result', opportunity.result_status).label}</span></div>
      <div className="grid min-h-[28px] grid-cols-[118px_minmax(0,1fr)] items-center gap-2 border-b border-[#f1ece3]"><span className="text-[10.5px] font-semibold text-slate-500">Contrato</span><span className="text-[11.5px] text-[#17202d]">{getOpportunityPresentation('contract', opportunity.contract_status).label}</span></div>
      <div className="grid min-h-[28px] grid-cols-[118px_minmax(0,1fr)] items-center gap-2 border-b border-[#f1ece3]"><span className="text-[10.5px] font-semibold text-slate-500">Colaborador atribuido</span><span className={attributedName ? 'text-[11.5px] text-[#17202d]' : 'text-[11.5px] text-slate-400'}>{attributedName ? person(attributedName) : 'Sin atribuir'}</span></div>
      {ownParticipation && <div className="grid min-h-[28px] grid-cols-[118px_minmax(0,1fr)] items-center gap-2"><span className="text-[10.5px] font-semibold text-slate-500">Mi participacion</span><span className="font-semibold text-[#17202d]">{compensationText(opportunity)}</span></div>}
    </div>
    {cue.label === 'Participacion pagada' && <p className="text-[11px] font-semibold text-emerald-700">✓ Participacion pagada</p>}
    {opportunity.service_name && <div className="grid gap-1 border-t border-[#f1ece3] pt-2"><div className="flex items-center justify-between gap-2"><span className="text-[10.5px] font-semibold text-slate-500">Servicio probable</span>{onOpenPlaybook && <button type="button" onClick={onOpenPlaybook} className="text-[11px] font-semibold text-[#235b3e]">Ver playbook</button>}</div><span className="text-[11.5px] font-semibold text-[#17202d]">{opportunity.service_name}</span></div>}
    <div className="grid gap-1 border-t border-[#f1ece3] pt-2"><span className="text-[10.5px] font-bold uppercase tracking-[0.08em] text-slate-500">Calificacion</span>{[['Dolor detectado', opportunity.pain_point], ['Necesidad', opportunity.identified_need], ['Que sabemos', opportunity.qualification_notes], ['Que falta', opportunity.missing_information], ['Que espera el cliente', opportunity.client_expectation]].map(([label, value]) => value ? <div key={label} className="grid grid-cols-[118px_minmax(0,1fr)] gap-2"><span className="text-[10.5px] font-semibold text-slate-500">{label}</span><span className="whitespace-pre-line text-[11.5px] text-[#17202d]">{value}</span></div> : null)}<span className={`text-[11px] font-semibold ${opportunity.requires_specialist ? 'text-amber-700' : 'text-slate-500'}`}>Especialista requerido: {opportunity.requires_specialist ? 'Si' : 'No'}</span></div>
  </div>
}

function QualificationEditor({ opportunity, services, onChange, onOpenPlaybook }: { opportunity: NonNullable<RedComercialProspectPanelRecord['opportunities']>[number]; services: RepresentedCompanyServiceRecord[]; onChange: (payload: Record<string, unknown>) => Promise<void>; onOpenPlaybook?: () => void }) {
  const [draft, setDraft] = useState({ pain_point: opportunity.pain_point ?? '', identified_need: opportunity.identified_need ?? '', qualification_notes: opportunity.qualification_notes ?? '', client_expectation: opportunity.client_expectation ?? '', missing_information: opportunity.missing_information ?? '' })
  useEffect(() => { setDraft({ pain_point: opportunity.pain_point ?? '', identified_need: opportunity.identified_need ?? '', qualification_notes: opportunity.qualification_notes ?? '', client_expectation: opportunity.client_expectation ?? '', missing_information: opportunity.missing_information ?? '' }) }, [opportunity.id, opportunity.pain_point, opportunity.identified_need, opportunity.qualification_notes, opportunity.client_expectation, opportunity.missing_information])
  const selectedService = services.find((service) => service.id === opportunity.represented_company_service_id)
  const updateText = (key: keyof typeof draft, value: string) => setDraft((current) => ({ ...current, [key]: value }))
  const saveText = (key: keyof typeof draft) => { if (draft[key] !== (opportunity[key] ?? '')) void onChange({ [key]: draft[key] }) }
  return <div className="grid gap-2 border-t border-[#eee8dd] pt-2"><div className="flex items-end gap-2"><label className="grid min-w-0 flex-1 gap-1 text-[11px] text-slate-500">Servicio probable<select value={opportunity.represented_company_service_id ?? ''} onChange={(event) => void onChange({ represented_company_service_id: event.target.value })} className="rounded border border-[#d7d0c4] bg-white px-2 py-1.5 text-[12px] text-[#17202d]"><option value="">Sin identificar</option>{services.filter((service) => service.is_active).map((service) => <option key={service.id} value={service.id}>{service.name}</option>)}</select></label>{selectedService && onOpenPlaybook && <button type="button" onClick={onOpenPlaybook} className="pb-1 text-[11px] font-semibold text-[#235b3e]">Ver playbook</button>}</div><div className="grid gap-2 sm:grid-cols-2"><label className="grid gap-1 text-[11px] text-slate-500">Dolor detectado<textarea value={draft.pain_point} onChange={(event) => updateText('pain_point', event.target.value)} onBlur={() => saveText('pain_point')} rows={2} className="rounded border border-[#d7d0c4] px-2 py-1.5 text-[12px]" /></label><label className="grid gap-1 text-[11px] text-slate-500">Necesidad concreta<textarea value={draft.identified_need} onChange={(event) => updateText('identified_need', event.target.value)} onBlur={() => saveText('identified_need')} rows={2} className="rounded border border-[#d7d0c4] px-2 py-1.5 text-[12px]" /></label><label className="grid gap-1 text-[11px] text-slate-500">Qué sabemos<textarea value={draft.qualification_notes} onChange={(event) => updateText('qualification_notes', event.target.value)} onBlur={() => saveText('qualification_notes')} rows={2} className="rounded border border-[#d7d0c4] px-2 py-1.5 text-[12px]" /></label><label className="grid gap-1 text-[11px] text-slate-500">Qué falta<textarea value={draft.missing_information} onChange={(event) => updateText('missing_information', event.target.value)} onBlur={() => saveText('missing_information')} rows={2} className="rounded border border-[#d7d0c4] px-2 py-1.5 text-[12px]" /></label></div><label className="grid gap-1 text-[11px] text-slate-500">Qué espera el cliente<textarea value={draft.client_expectation} onChange={(event) => updateText('client_expectation', event.target.value)} onBlur={() => saveText('client_expectation')} rows={2} className="rounded border border-[#d7d0c4] px-2 py-1.5 text-[12px]" /></label><label className="inline-flex items-center gap-2 text-[11px] font-semibold text-slate-600"><input type="checkbox" checked={Boolean(opportunity.requires_specialist)} onChange={(event) => void onChange({ requires_specialist: event.target.checked })} />Requiere especialista del representado</label></div>
}

function OpportunityEditor({ opportunity, collaborators, services, onChange, onOpenPlaybook, disabled }: { opportunity: NonNullable<RedComercialProspectPanelRecord['opportunities']>[number]; collaborators: CollaboratorRecord[]; services: RepresentedCompanyServiceRecord[]; onChange: (payload: Record<string, unknown>) => Promise<void>; onOpenPlaybook?: () => void; disabled?: boolean }) {
  const auth = useAdminAuth()
  const admin = isRedComercialAdmin(auth.profile)
  const readOnly = disabled ?? (!admin && opportunity.control_mode === 'arista')
  const select = (key: string, value: string) => { void onChange({ [key]: value }) }
  const labels: Record<string, string> = {
    collaborator: 'Gestion colaborador', arista: 'Gestion Arista', shared: 'Gestion compartida',
    in_process: 'En proceso', won: 'Ganada', lost: 'Perdida', cancelled: 'Cancelada',
    not_required: 'No requerido', pending: 'Pendiente', sent: 'Enviado', under_review: 'En revision',
    signed: 'Firmado', not_signed: 'No firmado', withdrawn: 'Retirado', not_applicable: 'No aplica',
    partial: 'Parcial', paid: 'Pagado', overdue: 'Vencido', refunded: 'Reembolsado',
    not_generated: 'No generada', to_validate: 'Por validar', generated: 'Generada', pending_payment: 'Pago pendiente', void: 'Anulada',
  }
  const attributedName = opportunity.attributed_collaborator_name || collaborators.find((item) => item.id === opportunity.attributed_collaborator_id)?.full_name || null
  const isAttributedUser = Boolean(opportunity.attributed_collaborator_id && opportunity.attributed_collaborator_id === auth.user?.id)
  if (!admin && !readOnly) return <><ReadOnlyOpportunity opportunity={opportunity} attributedName={attributedName} isAttributedUser={isAttributedUser} onOpenPlaybook={onOpenPlaybook} /><QualificationEditor opportunity={opportunity} services={services} onChange={onChange} onOpenPlaybook={onOpenPlaybook} /><ManualSpecialistRequestSection opportunity={opportunity} services={services} admin={admin} onOpenPlaybook={() => onOpenPlaybook?.()} /></>
  if (readOnly) return <><ReadOnlyOpportunity opportunity={opportunity} attributedName={attributedName} isAttributedUser={isAttributedUser} onOpenPlaybook={onOpenPlaybook} /><ManualSpecialistRequestSection opportunity={opportunity} services={services} admin={admin} onOpenPlaybook={() => onOpenPlaybook?.()} /></>
  const readOnlyRow = (label: string, value: string) => <div className="grid min-h-[28px] grid-cols-[118px_minmax(0,1fr)] items-center gap-2 border-b border-[#f1ece3]"><span className="text-[10.5px] font-semibold text-slate-500">{label}</span><span className="text-[11.5px] text-[#17202d]">{labels[value] ?? value}</span></div>
  const detailRow = (label: string, value: string | null) => <div className="grid min-h-[28px] grid-cols-[118px_minmax(0,1fr)] items-center gap-2 border-b border-[#f1ece3]"><span className="text-[10.5px] font-semibold text-slate-500">{label}</span><span className={value ? 'text-[11.5px] text-[#17202d]' : 'text-[11.5px] text-slate-400'}>{value || 'Sin definir'}</span></div>
  if (readOnly) return <div data-readonly="true" className="grid text-[12px]">{readOnlyRow('Control actual', opportunity.control_mode)}{readOnlyRow('Resultado', opportunity.result_status)}{readOnlyRow('Contrato', opportunity.contract_status)}{readOnlyRow('Pago cliente', opportunity.payment_status)}{readOnlyRow('Comision colaborador', opportunity.commission_status)}{detailRow('Colaborador atribuido', attributedName ? person(attributedName) : null)}{opportunity.attributed_collaborator_id && isAttributedUser && detailRow('Tu participacion atribuida', compensationText(opportunity))}</div>
  const selectedService = services.find((service) => service.id === opportunity.represented_company_service_id)
  const serviceOptions = services.filter((service) => service.is_active || service.id === opportunity.represented_company_service_id)
  return <div className="grid gap-1.5 text-[12px]">
    <div className="grid gap-2 rounded-md border border-[#dbeade] bg-[#f7faf7] p-2"><div className="flex items-end gap-2"><label className="grid min-w-0 flex-1 gap-1 text-slate-500">Servicio probable<select value={opportunity.represented_company_service_id ?? ''} onChange={(event) => select('represented_company_service_id', event.target.value)} className="rounded border border-[#d7d0c4] bg-white px-2 py-1.5 text-[#17202d]"><option value="">Sin identificar</option>{serviceOptions.map((service) => <option key={service.id} value={service.id}>{service.name}{!service.is_active ? ' · Inactivo' : ''}</option>)}</select></label>{selectedService && onOpenPlaybook && <button type="button" onClick={onOpenPlaybook} className="whitespace-nowrap pb-1 text-[11px] font-semibold text-[#235b3e]">Ver playbook</button>}</div>{selectedService?.discovery_questions && <details><summary className="cursor-pointer text-[11px] font-semibold text-[#235b3e]">Preguntas recomendadas</summary><p className="mt-1 whitespace-pre-line text-[11px] leading-5 text-slate-600">{selectedService.discovery_questions}</p></details>}{selectedService?.required_information && <p className="text-[11px] text-slate-600"><strong>Antes de derivar:</strong> {selectedService.required_information}</p>}</div>
    <div className="grid gap-2 border-t border-[#eee8dd] pt-2"><h4 className="text-[11px] font-bold uppercase tracking-[0.08em] text-slate-500">Calificacion</h4><div className="grid gap-2 sm:grid-cols-2"><label className="grid gap-1 text-slate-500">Dolor detectado<textarea value={opportunity.pain_point ?? ''} onChange={(event) => void onChange({ pain_point: event.target.value })} className="rounded border border-[#d7d0c4] px-2 py-1.5 text-[#17202d]" rows={2} /></label><label className="grid gap-1 text-slate-500">Necesidad concreta<textarea value={opportunity.identified_need ?? ''} onChange={(event) => void onChange({ identified_need: event.target.value })} className="rounded border border-[#d7d0c4] px-2 py-1.5 text-[#17202d]" rows={2} /></label><label className="grid gap-1 text-slate-500">Que sabemos<textarea value={opportunity.qualification_notes ?? ''} onChange={(event) => void onChange({ qualification_notes: event.target.value })} className="rounded border border-[#d7d0c4] px-2 py-1.5 text-[#17202d]" rows={2} /></label><label className="grid gap-1 text-slate-500">Que falta<textarea value={opportunity.missing_information ?? ''} onChange={(event) => void onChange({ missing_information: event.target.value })} className="rounded border border-[#d7d0c4] px-2 py-1.5 text-[#17202d]" rows={2} /></label></div><label className="grid gap-1 text-slate-500">Que espera el cliente<textarea value={opportunity.client_expectation ?? ''} onChange={(event) => void onChange({ client_expectation: event.target.value })} className="rounded border border-[#d7d0c4] px-2 py-1.5 text-[#17202d]" rows={2} /></label><label className="inline-flex items-center gap-2 text-[11px] font-semibold text-slate-600"><input type="checkbox" checked={Boolean(opportunity.requires_specialist)} onChange={(event) => void onChange({ requires_specialist: event.target.checked })} />Requiere especialista del representado</label></div>
    <div className="grid grid-cols-2 gap-2"><label className="grid gap-1 text-slate-500">Control actual<select value={opportunity.control_mode} onChange={(event) => select('control_mode', event.target.value)} className="rounded border border-[#d7d0c4] bg-white px-2 py-1.5 text-[#17202d]"><option value="collaborator">Gestion colaborador</option><option value="arista">Gestion Arista</option><option value="shared">Gestion compartida</option></select></label><label className="grid gap-1 text-slate-500">Resultado<select value={opportunity.result_status} onChange={(event) => select('result_status', event.target.value)} className="rounded border border-[#d7d0c4] bg-white px-2 py-1.5 text-[#17202d]"><option value="in_process">En proceso</option><option value="won">Ganada</option><option value="lost">Perdida</option><option value="cancelled">Cancelada</option></select></label></div>
    <div className="grid grid-cols-2 gap-2"><label className="grid gap-1 text-slate-500">Contrato<select value={opportunity.contract_status} onChange={(event) => select('contract_status', event.target.value)} className="rounded border border-[#d7d0c4] bg-white px-2 py-1.5 text-[#17202d]"><option value="not_required">No requerido</option><option value="pending">Pendiente</option><option value="sent">Enviado</option><option value="under_review">En revision</option><option value="signed">Firmado</option><option value="not_signed">No firmado</option><option value="withdrawn">Retirado</option><option value="cancelled">Cancelado</option></select></label><label className="grid gap-1 text-slate-500">Pago cliente<select value={opportunity.payment_status} onChange={(event) => select('payment_status', event.target.value)} className="rounded border border-[#d7d0c4] bg-white px-2 py-1.5 text-[#17202d]"><option value="not_applicable">No aplica</option><option value="pending">Pendiente</option><option value="partial">Parcial</option><option value="paid">Pagado</option><option value="overdue">Vencido</option><option value="refunded">Reembolsado</option><option value="cancelled">Cancelado</option></select></label></div>
    <label className="grid gap-1 text-slate-500">Comision colaborador<select value={opportunity.commission_status} onChange={(event) => select('commission_status', event.target.value)} className="rounded border border-[#d7d0c4] bg-white px-2 py-1.5 text-[#17202d]"><option value="not_generated">No generada</option><option value="to_validate">Por validar</option><option value="generated">Generada</option><option value="pending_payment">Pago pendiente</option><option value="paid">Pagada</option><option value="void">Anulada</option></select></label>
    <div className="grid grid-cols-2 gap-2"><label className="grid gap-1 text-slate-500">Colaborador atribuido<select value={opportunity.attributed_collaborator_id ?? ''} onChange={(event) => void onChange({ attributed_collaborator_id: event.target.value })} className="rounded border border-[#d7d0c4] bg-white px-2 py-1.5 text-[#17202d]"><option value="">Sin atribuir</option>{collaborators.map((collaborator) => <option key={collaborator.id} value={collaborator.id}>{collaborator.full_name || collaborator.email}</option>)}</select></label><label className="grid gap-1 text-slate-500">Tipo de participacion<select value={opportunity.collaborator_compensation_type ?? ''} onChange={(event) => void onChange({ collaborator_compensation_type: event.target.value })} className="rounded border border-[#d7d0c4] bg-white px-2 py-1.5 text-[#17202d]"><option value="">Sin participacion</option><option value="percentage">Porcentaje</option><option value="fixed_amount">Monto fijo</option></select></label></div>
    <div className="grid grid-cols-2 gap-2"><label className="grid gap-1 text-slate-500">Porcentaje<input type="number" min="0" step="0.01" value={opportunity.collaborator_compensation_rate ?? ''} onChange={(event) => void onChange({ collaborator_compensation_rate: event.target.value })} className="rounded border border-[#d7d0c4] bg-white px-2 py-1.5 text-[#17202d]" /></label><label className="grid gap-1 text-slate-500">Monto fijo<input type="number" min="0" step="1" value={opportunity.collaborator_compensation_amount ?? ''} onChange={(event) => void onChange({ collaborator_compensation_amount: event.target.value })} className="rounded border border-[#d7d0c4] bg-white px-2 py-1.5 text-[#17202d]" /></label></div>
    {detailRow('Participacion atribuida', compensationText(opportunity))}
    <ManualSpecialistRequestSection opportunity={opportunity} services={services} admin={admin} onOpenPlaybook={() => onOpenPlaybook?.()} />
  </div>
}

function NewOpportunityModal({ prospectId, collaborators, services, isAdmin, onClose, onSaved }: { prospectId: string; collaborators: CollaboratorRecord[]; services: RepresentedCompanyServiceRecord[]; isAdmin: boolean; onClose: () => void; onSaved: (data: RedComercialProspectPanelRecord) => void }) {
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState('')
  async function submit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault(); setSaving(true); setError('')
    const data = new FormData(event.currentTarget)
    const selectedCompensationType = String(data.get('compensation_type') ?? '').trim()
    const attributedCollaboratorId = String(data.get('attributed_collaborator_id') ?? '')
    const compensationValue = String(data.get('compensation_rate') ?? '').trim()
    if (isAdmin && selectedCompensationType && !attributedCollaboratorId) {
      setSaving(false); setError('Selecciona un colaborador atribuido para registrar participacion.')
      return
    }
    const compensationNumber = compensationValue === '' ? null : Number(compensationValue)
    if (selectedCompensationType === 'percentage' && (compensationNumber === null || !Number.isFinite(compensationNumber) || compensationNumber < 0 || compensationNumber > 100)) {
      setSaving(false); setError('La participacion debe ser un porcentaje entre 0 y 100.')
      return
    }
    if (selectedCompensationType === 'fixed_amount' && (compensationNumber === null || !Number.isFinite(compensationNumber) || compensationNumber < 0)) {
      setSaving(false); setError('Ingresa un monto fijo valido.')
      return
    }
    const result = await adminRepository.createRedComercialOpportunity(prospectId, { control_mode: data.get('control_mode'), represented_company_service_id: data.get('represented_company_service_id') || null, pain_point: data.get('pain_point'), identified_need: data.get('identified_need'), qualification_notes: data.get('qualification_notes'), client_expectation: data.get('client_expectation'), missing_information: data.get('missing_information'), requires_specialist: data.get('requires_specialist') === 'on', attributed_collaborator_id: attributedCollaboratorId || null, collaborator_compensation_type: selectedCompensationType || null, collaborator_compensation_rate: selectedCompensationType === 'percentage' ? compensationNumber : null, collaborator_compensation_amount: selectedCompensationType === 'fixed_amount' ? compensationNumber : null })
    setSaving(false)
    if (result.error || !result.data) { setError(result.error ?? 'No fue posible crear la oportunidad.'); return }
    onSaved(result.data); onClose()
  }
  const activeServices = services.filter((service) => service.is_active)
  return <AdminDetailModal title="Crear oportunidad" onClose={onClose}><form className="grid gap-3 text-sm" onSubmit={(event) => void submit(event)}>{error && <p className="rounded bg-rose-50 px-3 py-2 text-rose-800">{error}</p>}<label className="grid gap-1 font-medium text-slate-700">Servicio probable<select name="represented_company_service_id" defaultValue="" className="rounded border border-[#c9c1b4] px-3 py-2"><option value="">Sin identificar</option>{activeServices.map((service) => <option key={service.id} value={service.id}>{service.name}</option>)}</select></label><div className="grid gap-2 sm:grid-cols-2"><label className="grid gap-1 font-medium text-slate-700">Dolor detectado<textarea name="pain_point" rows={2} className="rounded border border-[#c9c1b4] px-3 py-2" /></label><label className="grid gap-1 font-medium text-slate-700">Necesidad concreta<textarea name="identified_need" rows={2} className="rounded border border-[#c9c1b4] px-3 py-2" /></label></div><label className="grid gap-1 font-medium text-slate-700">Qué espera el cliente<textarea name="client_expectation" rows={2} className="rounded border border-[#c9c1b4] px-3 py-2" /></label><label className="inline-flex items-center gap-2 font-medium text-slate-700"><input name="requires_specialist" type="checkbox" />Requiere especialista del representado</label><label className="grid gap-1 font-medium text-slate-700">Control actual<select name="control_mode" defaultValue="collaborator" className="rounded border border-[#c9c1b4] px-3 py-2"><option value="collaborator">Gestion colaborador</option><option value="arista">Gestion Arista</option><option value="shared">Gestion compartida</option></select></label>{isAdmin && <label className="grid gap-1 font-medium text-slate-700">Colaborador atribuido<select name="attributed_collaborator_id" defaultValue="" className="rounded border border-[#c9c1b4] px-3 py-2"><option value="">Sin atribuir</option>{collaborators.map((collaborator) => <option key={collaborator.id} value={collaborator.id}>{collaborator.full_name || collaborator.email}</option>)}</select></label>}<label className="grid gap-1 font-medium text-slate-700">Tipo de participacion<select name="compensation_type" defaultValue="" className="rounded border border-[#c9c1b4] px-3 py-2"><option value="">Sin participacion</option><option value="percentage">Porcentaje</option><option value="fixed_amount">Monto fijo</option></select></label><label className="grid gap-1 font-medium text-slate-700">Participacion atribuida<input name="compensation_rate" type="number" min="0" step="0.01" className="rounded border border-[#c9c1c4] px-3 py-2" /></label><div className="flex justify-end gap-2"><button type="button" onClick={onClose} className="rounded border border-[#c9c1b4] px-3 py-2 font-semibold">Cancelar</button><button disabled={saving} className="rounded bg-[#235b3e] px-3 py-2 font-semibold text-white">Crear oportunidad</button></div></form></AdminDetailModal>
}

function CrossOpportunityModal({ prospectId, companies, currentCompanyId, onClose, onSaved }: { prospectId: string; companies: RepresentedCompanyRecord[]; currentCompanyId: string; onClose: () => void; onSaved: (data: RedComercialProspectPanelRecord) => void }) {
  const [error, setError] = useState(''); const [saving, setSaving] = useState(false)
  async function submit(event: React.FormEvent<HTMLFormElement>) { event.preventDefault(); setSaving(true); const data = new FormData(event.currentTarget); const result = await adminRepository.createRedComercialCrossOpportunity(prospectId, String(data.get('target_company_id') ?? ''), String(data.get('reason') ?? '')); setSaving(false); if (result.error || !result.data) { setError(result.error ?? 'No fue posible registrar la oportunidad.'); return } onSaved(result.data); onClose() }
  return <AdminDetailModal title="Agregar oportunidad cruzada" onClose={onClose}><form className="grid gap-3 text-sm" onSubmit={(event) => void submit(event)}>{error && <p className="rounded bg-rose-50 px-3 py-2 text-rose-800">{error}</p>}<label className="grid gap-1 font-medium text-slate-700">Empresa Arista destino *<select name="target_company_id" required className="rounded border border-[#c9c1b4] px-3 py-2"><option value="">Seleccionar</option>{companies.filter((company) => company.id !== currentCompanyId && company.status === 'active').map((company) => <option key={company.id} value={company.id}>{company.name}</option>)}</select></label><label className="grid gap-1 font-medium text-slate-700">Por que detectaste esta oportunidad? *<textarea name="reason" required rows={4} className="rounded border border-[#c9c1b4] px-3 py-2" /></label><div className="flex justify-end gap-2"><button type="button" onClick={onClose} className="rounded border border-[#c9c1b4] px-3 py-2 font-semibold">Cancelar</button><button disabled={saving} className="rounded bg-[#235b3e] px-3 py-2 font-semibold text-white">Registrar oportunidad</button></div></form></AdminDetailModal>
}

