function SpecialistRequestModal({ opportunity, current, services, onClose, onSaved }: { opportunity: NonNullable<RedComercialProspectPanelRecord['opportunities']>[number]; current: RedComercialProspectDetailRecord | null; services: RepresentedCompanyServiceRecord[]; onClose: () => void; onSaved: (request: RedComercialSpecialistRequestRecord) => void }) {
  const [saving, setSaving] = useState(false); const [error, setError] = useState('')
  async function submit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault(); setSaving(true); setError(''); const data = new FormData(event.currentTarget)
    const result = await adminRepository.createRedComercialSpecialistRequest(opportunity.id, {
      represented_company_service_id: opportunity.represented_company_service_id || '',
      need_summary: data.get('need_summary'), conversation_summary: data.get('conversation_summary'),
      client_expectation: data.get('client_expectation'), missing_information: data.get('missing_information'),
      proposed_date: data.get('proposed_date') ? new Date(String(data.get('proposed_date'))).toISOString() : '', notes: data.get('notes'),
    })
    setSaving(false); if (result.error || !result.data) { setError(result.error ?? 'No fue posible enviar la solicitud.'); return }; onSaved(result.data); onClose()
  }
  return <AdminDetailModal title="Solicitar especialista" onClose={onClose}><form className="grid gap-3 text-sm" onSubmit={(event) => void submit(event)}>{error && <p className="rounded bg-rose-50 px-3 py-2 text-rose-800">{error}</p>}<div className="admin-specialist-context rounded border border-[#d9e7dc] bg-[#f4f8f5] px-3 py-2 text-[11px] text-slate-600"><strong className="text-[#17202d]">{current?.company_name ?? 'Empresa representada'}</strong><span className="mx-1">·</span>{services.find((service) => service.id === opportunity.represented_company_service_id)?.name ?? 'Servicio por identificar'}<p className="mt-1">{current?.contact_name || 'Contacto sin definir'}</p></div><label className="grid gap-1 font-medium text-slate-700">Resumen para el especialista<textarea name="need_summary" defaultValue={opportunity.identified_need || opportunity.pain_point || ''} rows={3} className="rounded border border-[#c9c1b4] px-3 py-2" /></label><label className="grid gap-1 font-medium text-slate-700">Resumen de conversación<textarea name="conversation_summary" defaultValue={opportunity.qualification_notes || ''} rows={3} className="rounded border border-[#c9c1b4] px-3 py-2" /></label><div className="grid gap-2 sm:grid-cols-2"><label className="grid gap-1 font-medium text-slate-700">Qué espera el cliente<textarea name="client_expectation" defaultValue={opportunity.client_expectation || ''} rows={2} className="rounded border border-[#c9c1b4] px-3 py-2" /></label><label className="grid gap-1 font-medium text-slate-700">Información faltante<textarea name="missing_information" defaultValue={opportunity.missing_information || ''} rows={2} className="rounded border border-[#c9c1b4] px-3 py-2" /></label></div><label className="grid gap-1 font-medium text-slate-700">Fecha sugerida<input name="proposed_date" type="datetime-local" className="rounded border border-[#c9c1b4] px-3 py-2" /></label><label className="grid gap-1 font-medium text-slate-700">Observaciones<textarea name="notes" rows={2} className="rounded border border-[#c9c1b4] px-3 py-2" /></label><div className="flex justify-end gap-2"><button type="button" onClick={onClose} className="rounded border border-[#c9c1b4] px-3 py-2 font-semibold">Cancelar</button><button disabled={saving} className="rounded bg-[#235b3e] px-3 py-2 font-semibold text-white">{saving ? 'Enviando...' : 'Enviar solicitud'}</button></div></form></AdminDetailModal>
}

function SpecialistOutcomeModal({ request, canEdit, onClose, onSaved }: { request: RedComercialSpecialistRequestRecord; canEdit: boolean; onClose: () => void; onSaved: (request: RedComercialSpecialistRequestRecord) => void }) {
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState('')
  async function submit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault()
    if (!canEdit) return
    setSaving(true)
    setError('')
    const data = new FormData(event.currentTarget)
    const followup = String(data.get('next_followup_at') ?? '')
    const result = await adminRepository.recordRedComercialSpecialistOutcome(request.id, {
      meeting_summary: data.get('meeting_summary'),
      meeting_outcome: data.get('meeting_outcome'),
      next_action: data.get('next_action'),
      next_followup_at: followup ? new Date(followup).toISOString() : '',
      notes: data.get('notes'),
    })
    setSaving(false)
    if (result.error || !result.data) { setError(result.error ?? 'No fue posible guardar el resultado.'); return }
    onSaved(result.data)
    onClose()
  }
  const localFollowup = request.next_followup_at ? new Date(request.next_followup_at).toISOString().slice(0, 16) : ''
  return <AdminDetailModal title={request.meeting_summary ? (canEdit ? 'Editar resultado de reunion' : 'Resultado de reunion') : 'Registrar resultado de reunion'} onClose={onClose}>
    <form className="grid gap-3 text-sm" onSubmit={(event) => void submit(event)}>
      {error && <p className="rounded bg-rose-50 px-3 py-2 text-rose-800">{error}</p>}
      <label className="grid gap-1 font-medium text-slate-700">Resumen de la reunion *<textarea name="meeting_summary" required defaultValue={request.meeting_summary ?? ''} disabled={!canEdit} rows={4} className="rounded border border-[#c9c1b4] px-3 py-2" /></label>
      <label className="grid gap-1 font-medium text-slate-700">Resultado<select name="meeting_outcome" defaultValue={request.meeting_outcome ?? ''} disabled={!canEdit} className="rounded border border-[#c9c1b4] px-3 py-2"><option value="">Sin definir</option>{Object.entries(specialistOutcomeLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label>
      <label className="grid gap-1 font-medium text-slate-700">Proxima accion *<textarea name="next_action" required defaultValue={request.next_action ?? ''} disabled={!canEdit} rows={3} className="rounded border border-[#c9c1b4] px-3 py-2" /></label>
      <label className="grid gap-1 font-medium text-slate-700">Proximo seguimiento<input name="next_followup_at" type="datetime-local" defaultValue={localFollowup} disabled={!canEdit} className="rounded border border-[#c9c1b4] px-3 py-2" /></label>
      <label className="grid gap-1 font-medium text-slate-700">Observaciones adicionales<textarea name="notes" defaultValue={request.notes ?? ''} disabled={!canEdit} rows={2} className="rounded border border-[#c9c1b4] px-3 py-2" /></label>
      <div className="flex justify-end gap-2"><button type="button" onClick={onClose} className="rounded border border-[#c9c1b4] px-3 py-2 font-semibold">Cerrar</button>{canEdit && <button disabled={saving} className="rounded bg-[#235b3e] px-3 py-2 font-semibold text-white">{saving ? 'Guardando...' : 'Guardar resultado'}</button>}</div>
    </form>
  </AdminDetailModal>
}

export function SpecialistRequestSectionLegacy({ opportunity, current, services, admin, onOpenPlaybook, onError: _onError }: { opportunity: NonNullable<RedComercialProspectPanelRecord['opportunities']>[number]; current: RedComercialProspectDetailRecord | null; services: RepresentedCompanyServiceRecord[]; admin: boolean; onOpenPlaybook: () => void; onError: (message: string) => void }) {
  const [modal, setModal] = useState(false); const [scheduleModal, setScheduleModal] = useState(false); const [request, setRequest] = useState<RedComercialSpecialistRequestRecord | null>(null); const [calendarUrl, setCalendarUrl] = useState(''); const [savingCalendar, setSavingCalendar] = useState(false); const [requestError, setRequestError] = useState('')
  useEffect(() => { if (!opportunity.requires_specialist || typeof adminRepository.getRedComercialSpecialistRequest !== 'function') { setRequest(null); return }; adminRepository.getRedComercialSpecialistRequest(opportunity.id).then((result) => { if (result.error) setRequestError(result.error); else { setRequest(result.data); setCalendarUrl(result.data?.technical_calendar_url ?? '') } }) }, [opportunity.id, opportunity.requires_specialist])
  useEffect(() => { setCalendarUrl(request?.technical_calendar_url ?? '') }, [request?.technical_calendar_url])
  const canRequest = opportunity.requires_specialist && !request && (admin || opportunity.control_mode !== 'arista') && opportunity.result_status === 'in_process'
  async function review(action: 'approve' | 'schedule' | 'complete' | 'cancel', scheduledAt?: string) { const result = await adminRepository.reviewRedComercialSpecialistRequest(request!.id, action, scheduledAt); if (result.error || !result.data) setRequestError(result.error ?? 'No fue posible actualizar la solicitud.'); else setRequest(result.data); setScheduleModal(false) }
  async function saveCalendar() { setSavingCalendar(true); const companyId = current?.represented_company_id ?? String(opportunity.represented_company_id ?? ''); const result = await adminRepository.updateRedComercialCompanyCalendarUrl(companyId, calendarUrl); setSavingCalendar(false); if (result.error) setRequestError(result.error); else if (request) setRequest({ ...request, technical_calendar_url: result.data }) }
  return <PanelSection title="Especialista" action={canRequest && <button type="button" onClick={() => setModal(true)} className="inline-flex items-center gap-1 text-[11px] font-semibold text-[#235b3e]"><Plus size={13} />Solicitar especialista</button>}><div className="grid gap-1.5 text-[11px]">{requestError && <p className="rounded bg-rose-50 px-2 py-1 text-rose-800">{requestError}</p>}{!request ? <><div className="flex items-center gap-2"><span className="rounded-full bg-amber-50 px-2 py-1 font-semibold text-amber-800">Especialista requerido</span><span className="text-slate-500">Aún no solicitado</span></div>{!canRequest && opportunity.control_mode === 'arista' && <p className="text-slate-500">La oportunidad está en gestión Arista.</p>}</> : <><div className="flex items-center justify-between gap-2"><div><p className="font-semibold text-[#17202d]">{specialistStatusLabels[request.status] ?? request.status}</p><p className="text-slate-500">{date(request.scheduled_at || request.created_at)}</p></div>{request.status === 'approved' && request.technical_calendar_url && <button type="button" onClick={() => window.open(request.technical_calendar_url!, '_blank', 'noopener,noreferrer')} className="inline-flex items-center gap-1 rounded border border-[#c9dfd0] px-2 py-1 font-semibold text-[#235b3e]"><ExternalLink size={12} />Abrir agenda</button>}</div><div className="flex flex-wrap items-center gap-2">{request.status === 'approved' && !request.technical_calendar_url && admin && <span className="text-amber-700">Agenda del representado pendiente</span>}{admin && request.status === 'requested' && <><button type="button" onClick={() => void review('approve')} className="rounded bg-[#235b3e] px-2 py-1 font-semibold text-white">Aprobar</button><button type="button" onClick={() => void review('cancel')} className="rounded border border-[#c9c1b4] px-2 py-1 font-semibold">Cancelar</button></>}{admin && request.status === 'approved' && <><button type="button" onClick={() => setScheduleModal(true)} className="rounded border border-[#c9c1b4] px-2 py-1 font-semibold"><Calendar size={12} className="mr-1 inline" />Marcar agendada</button><button type="button" onClick={() => void review('cancel')} className="rounded border border-[#c9c1b4] px-2 py-1 font-semibold">Cancelar</button></>}{admin && request.status === 'scheduled' && <><button type="button" onClick={() => void review('complete')} className="rounded bg-[#235b3e] px-2 py-1 font-semibold text-white">Marcar realizada</button><button type="button" onClick={() => void review('cancel')} className="rounded border border-[#c9c1b4] px-2 py-1 font-semibold">Cancelar</button></>}</div></>}{admin && !request?.technical_calendar_url && <div className="mt-1 flex items-center gap-2"><input aria-label="Agenda del representado" value={calendarUrl} onChange={(event) => setCalendarUrl(event.target.value)} placeholder="URL de agenda del representado" className="min-w-0 flex-1 rounded border border-[#c9c1b4] px-2 py-1" /><button type="button" onClick={() => void saveCalendar()} disabled={savingCalendar} className="rounded border border-[#c9c1b4] px-2 py-1 font-semibold">Guardar</button></div>}<button type="button" onClick={onOpenPlaybook} className="text-left font-semibold text-[#235b3e]">Ver playbook del servicio →</button></div>{modal && <SpecialistRequestModal opportunity={opportunity} current={current} services={services} onClose={() => setModal(false)} onSaved={(value) => setRequest(value)} />}{scheduleModal && <AdminDetailModal title="Marcar reunión agendada" onClose={() => setScheduleModal(false)}><form className="grid gap-3" onSubmit={(event) => { event.preventDefault(); const value = String(new FormData(event.currentTarget).get('scheduled_at') ?? ''); if (value) void review('schedule', new Date(value).toISOString()) }}><label className="grid gap-1 text-sm font-medium">Fecha y hora<input required name="scheduled_at" type="datetime-local" className="rounded border border-[#c9c1b4] px-3 py-2" /></label><div className="flex justify-end gap-2"><button type="button" onClick={() => setScheduleModal(false)} className="rounded border border-[#c9c1b4] px-3 py-2 font-semibold">Cancelar</button><button className="rounded bg-[#235b3e] px-3 py-2 font-semibold text-white">Guardar</button></div></form></AdminDetailModal>}</PanelSection>
}

export function ManualSpecialistRequestSectionLegacy({ opportunity, services, admin, onOpenPlaybook }: { opportunity: NonNullable<RedComercialProspectPanelRecord['opportunities']>[number]; services: RepresentedCompanyServiceRecord[]; admin: boolean; onOpenPlaybook: () => void }) {
  const [request, setRequest] = useState<RedComercialSpecialistRequestRecord | null>(null)
  const [requestModal, setRequestModal] = useState(false)
  const [scheduleModal, setScheduleModal] = useState(false)
  const [error, setError] = useState('')
  useEffect(() => { if (!opportunity.requires_specialist) { setRequest(null); return }; void adminRepository.getRedComercialSpecialistRequest(opportunity.id).then((result) => { if (result.error) setError(result.error); else setRequest(result.data) }) }, [opportunity.id, opportunity.requires_specialist])
  if (!opportunity.requires_specialist) return null
  const canRequest = !request && (admin || opportunity.control_mode !== 'arista') && opportunity.result_status === 'in_process'
  async function review(action: 'schedule' | 'complete' | 'cancel', scheduledAt?: string) { if (!request) return; const result = await adminRepository.reviewRedComercialSpecialistRequest(request.id, action, scheduledAt); if (result.error || !result.data) setError(result.error ?? 'No fue posible actualizar la solicitud.'); else setRequest(result.data); setScheduleModal(false) }
  return <PanelSection title="Especialista" action={canRequest && <button type="button" onClick={() => setRequestModal(true)} className="inline-flex items-center gap-1 text-[11px] font-semibold text-[#235b3e]"><Plus size={13} />Solicitar especialista</button>}><div className="grid gap-1.5 text-[11px]">{error && <p className="rounded bg-rose-50 px-2 py-1 text-rose-800">{error}</p>}{!request ? <div className="flex items-center gap-2"><span className="rounded-full bg-amber-50 px-2 py-1 font-semibold text-amber-800">Especialista requerido</span><span className="text-slate-500">{canRequest ? 'Aún no solicitado' : opportunity.control_mode === 'arista' ? 'Gestión Arista' : 'No disponible'}</span></div> : <><div className="flex items-center justify-between gap-2"><div><p className="font-semibold text-[#17202d]">{specialistStatusLabels[request.status] ?? request.status}</p><p className="text-slate-500">{date(request.scheduled_at || request.created_at)}</p></div><button type="button" onClick={() => setRequestModal(true)} className="font-semibold text-[#235b3e]">Ver solicitud</button></div>{admin && <div className="flex flex-wrap gap-2">{request.status === 'requested' && <button type="button" onClick={() => setScheduleModal(true)} className="rounded border border-[#c9c1b4] px-2 py-1 font-semibold">Agendar reunión</button>}{request.status === 'scheduled' && <button type="button" onClick={() => void review('complete')} className="rounded bg-[#235b3e] px-2 py-1 font-semibold text-white">Marcar realizada</button>}{['requested', 'scheduled'].includes(request.status) && <button type="button" onClick={() => void review('cancel')} className="rounded border border-[#c9c1b4] px-2 py-1 font-semibold">Cancelar</button>}</div>}</>}{opportunity.represented_company_service_id && <button type="button" onClick={onOpenPlaybook} className="text-left font-semibold text-[#235b3e]">Ver playbook del servicio →</button>}</div>{requestModal && <SpecialistRequestModal opportunity={opportunity} current={null} services={services} onClose={() => setRequestModal(false)} onSaved={(value) => { setRequest(value); setRequestModal(false) }} />}{scheduleModal && <AdminDetailModal title="Agendar reunión" onClose={() => setScheduleModal(false)}><form className="grid gap-3" onSubmit={(event) => { event.preventDefault(); const value = String(new FormData(event.currentTarget).get('scheduled_at') ?? ''); if (value) void review('schedule', new Date(value).toISOString()) }}><div className="grid gap-2 sm:grid-cols-2"><label className="grid gap-1 text-sm font-medium">Fecha *<input required name="scheduled_at" type="datetime-local" className="rounded border border-[#c9c1b4] px-3 py-2" /></label><label className="grid gap-1 text-sm font-medium">Contacto / especialista<input name="specialist_contact" className="rounded border border-[#c9c1b4] px-3 py-2" /></label></div><div className="flex justify-end gap-2"><button type="button" onClick={() => setScheduleModal(false)} className="rounded border border-[#c9c1b4] px-3 py-2 font-semibold">Cancelar</button><button className="rounded bg-[#235b3e] px-3 py-2 font-semibold text-white">Guardar</button></div></form></AdminDetailModal>}</PanelSection>
}

function ManualSpecialistRequestSection({ opportunity, services, admin, onOpenPlaybook }: { opportunity: NonNullable<RedComercialProspectPanelRecord['opportunities']>[number]; services: RepresentedCompanyServiceRecord[]; admin: boolean; onOpenPlaybook: () => void }) {
  const [request, setRequest] = useState<RedComercialSpecialistRequestRecord | null>(null)
  const [requestModal, setRequestModal] = useState(false)
  const [scheduleModal, setScheduleModal] = useState(false)
  const [outcomeModal, setOutcomeModal] = useState(false)
  const [error, setError] = useState('')
  useEffect(() => {
    if (!opportunity.requires_specialist) { setRequest(null); return }
    void adminRepository.getRedComercialSpecialistRequest(opportunity.id).then((result) => {
      if (result.error) setError(result.error)
      else setRequest(result.data)
    })
  }, [opportunity.id, opportunity.requires_specialist])
  if (!opportunity.requires_specialist) return null
  const canRequest = !request && (admin || opportunity.control_mode !== 'arista') && opportunity.result_status === 'in_process'
  async function review(action: 'schedule' | 'complete' | 'cancel', scheduledAt?: string) {
    if (!request) return
    const result = await adminRepository.reviewRedComercialSpecialistRequest(request.id, action, scheduledAt)
    if (result.error || !result.data) setError(result.error ?? 'No fue posible actualizar la solicitud.')
    else setRequest(result.data)
    setScheduleModal(false)
  }
  return <PanelSection title="Especialista" action={canRequest && <button type="button" onClick={() => setRequestModal(true)} className="inline-flex items-center gap-1 text-[11px] font-semibold text-[#235b3e]"><Plus size={13} />Solicitar especialista</button>}>
    <div className="grid gap-1.5 text-[11px]">
      {error && <p className="rounded bg-rose-50 px-2 py-1 text-rose-800">{error}</p>}
      {!request ? <div className="flex items-center gap-2"><span className="rounded-full bg-amber-50 px-2 py-1 font-semibold text-amber-800">Especialista requerido</span><span className="text-slate-500">Aun no solicitado</span></div> : <>
        <div className="flex items-center justify-between gap-2"><div><p className="font-semibold text-[#17202d]">{specialistStatusLabels[request.status] ?? request.status}</p><p className="text-slate-500">{date(request.scheduled_at || request.created_at)}</p></div><button type="button" onClick={() => setRequestModal(true)} className="font-semibold text-[#235b3e]">Ver solicitud</button></div>
        {request.status === 'completed' && <div className="grid gap-1 border-t border-[#f1ece3] pt-2"><div className="flex items-center justify-between gap-2"><span className="font-semibold text-[#17202d]">Resultado de reunion</span><button type="button" onClick={() => setOutcomeModal(true)} className="font-semibold text-[#235b3e]">{request.meeting_summary ? (admin ? 'Editar resultado' : 'Ver resultado') : 'Registrar resultado'}</button></div>{request.meeting_summary ? <div><p><span className="font-semibold text-slate-500">Resultado:</span> {request.meeting_outcome ? specialistOutcomeLabels[request.meeting_outcome] : 'Sin definir'}</p><p><span className="font-semibold text-slate-500">Proxima accion:</span> {request.next_action}</p>{request.next_followup_at && <p><span className="font-semibold text-slate-500">Proximo seguimiento:</span> {dateTime(request.next_followup_at)}</p>}</div> : <p className="text-slate-500">Aun no se ha registrado.</p>}</div>}
        {admin && <div className="flex flex-wrap gap-2">{request.status === 'requested' && <button type="button" onClick={() => setScheduleModal(true)} className="rounded border border-[#c9c1b4] px-2 py-1 font-semibold">Agendar reunion</button>}{request.status === 'scheduled' && <button type="button" onClick={() => void review('complete')} className="rounded bg-[#235b3e] px-2 py-1 font-semibold text-white">Marcar realizada</button>}{['requested', 'scheduled'].includes(request.status) && <button type="button" onClick={() => void review('cancel')} className="rounded border border-[#c9c1b4] px-2 py-1 font-semibold">Cancelar</button>}</div>}
      </>}
      {opportunity.represented_company_service_id && <button type="button" onClick={onOpenPlaybook} className="text-left font-semibold text-[#235b3e]">Ver playbook del servicio -&gt;</button>}
    </div>
    {requestModal && <SpecialistRequestModal opportunity={opportunity} current={null} services={services} onClose={() => setRequestModal(false)} onSaved={(value) => { setRequest(value); setRequestModal(false) }} />}
    {outcomeModal && request && <SpecialistOutcomeModal request={request} canEdit={admin} onClose={() => setOutcomeModal(false)} onSaved={(value) => setRequest(value)} />}
    {scheduleModal && <AdminDetailModal title="Agendar reunion" onClose={() => setScheduleModal(false)}><form className="grid gap-3" onSubmit={(event) => { event.preventDefault(); const value = String(new FormData(event.currentTarget).get('scheduled_at') ?? ''); if (value) void review('schedule', new Date(value).toISOString()) }}><div className="grid gap-2 sm:grid-cols-2"><label className="grid gap-1 text-sm font-medium">Fecha *<input required name="scheduled_at" type="datetime-local" className="rounded border border-[#c9c1b4] px-3 py-2" /></label><label className="grid gap-1 text-sm font-medium">Contacto / especialista<input name="specialist_contact" className="rounded border border-[#c9c1b4] px-3 py-2" /></label></div><div className="flex justify-end gap-2"><button type="button" onClick={() => setScheduleModal(false)} className="rounded border border-[#c9c1b4] px-3 py-2 font-semibold">Cancelar</button><button className="rounded bg-[#235b3e] px-3 py-2 font-semibold text-white">Guardar</button></div></form></AdminDetailModal>}
  </PanelSection>
}

export function RedComercialProspectDetailPanel({ prospect, opportunityId, onClose, onEdit, onActivity, onArchive, onSchedule, onChanged }: PanelProps) {
  const auth = useAdminAuth(); const admin = isRedComercialAdmin(auth.profile)
  const [tab, setTab] = useState<'summary' | 'activities' | 'files' | 'notes'>('summary')
  const [panel, setPanel] = useState<RedComercialProspectPanelRecord | null>(null)
  const [loading, setLoading] = useState(true); const [error, setError] = useState('')
  const [opportunityModal, setOpportunityModal] = useState(false); const [crossModal, setCrossModal] = useState(false); const [noteModal, setNoteModal] = useState(false); const [companies, setCompanies] = useState<RepresentedCompanyRecord[]>([])
  const [collaborators, setCollaborators] = useState<CollaboratorRecord[]>([])
  const [services, setServices] = useState<RepresentedCompanyServiceRecord[]>([])
  const [playbookService, setPlaybookService] = useState<RepresentedCompanyServiceRecord | null>(null)
  const current = panel?.prospect ?? prospect
  const opportunity = panel?.opportunities[0]
  const canCreateOpportunity = canCreateOpportunityForProspect(current)

  const loadPanel = useCallback(async () => { setLoading(true); setError(''); const result = opportunityId ? await adminRepository.getRedComercialOpportunityPanel(opportunityId) : await adminRepository.getRedComercialProspectPanel(prospect.id); if (result.data) setPanel(result.data); else if (result.error) { setPanel(null); setError(result.error) }; setLoading(false) }, [opportunityId, prospect.id])
  useEffect(() => { void loadPanel() }, [loadPanel])
  useEffect(() => { if (!admin) return; adminRepository.listCollaborators().then((result) => setCollaborators(result.data)) }, [admin])
  useEffect(() => { if (!current.represented_company_id || typeof adminRepository.listRedComercialCompanyServices !== 'function') return; adminRepository.listRedComercialCompanyServices(current.represented_company_id).then((result) => setServices(result.data)) }, [current.represented_company_id])
  useEffect(() => { function onKeyDown(event: KeyboardEvent) { if (event.key === 'Escape') onClose() } document.addEventListener('keydown', onKeyDown); return () => document.removeEventListener('keydown', onKeyDown) }, [onClose])
  async function refresh(data?: RedComercialProspectPanelRecord | null) { if (data) setPanel(data); else await loadPanel(); onChanged?.() }
  function openOpportunity(id: string) { window.location.assign(`/admin/oportunidades?opportunityId=${encodeURIComponent(id)}`) }
  async function updateOpportunity(payload: Record<string, unknown>) { if (!opportunity) return; const result = await adminRepository.updateRedComercialOpportunity(opportunity.id, payload); if (result.error) setError(result.error); else await refresh(result.data) }
  async function changeStatus(status: RedComercialProspectStatus) { const result = await adminRepository.updateRedComercialProspect(current.id, { status }); if (result.error) setError(result.error); else await refresh() }
  async function loadCompanies() { const result = admin ? await adminRepository.listRepresentedCompanies() : await adminRepository.listMyRepresentedCompanies(); setCompanies(result.data) }
  async function submitNote(event: React.FormEvent<HTMLFormElement>) { event.preventDefault(); const body = String(new FormData(event.currentTarget).get('body') ?? ''); const result = await adminRepository.createRedComercialProspectNote(current.id, body); if (result.error) setError(result.error); else { setNoteModal(false); await refresh(result.data) } }
  async function uploadFile(event: React.ChangeEvent<HTMLInputElement>) { const file = event.target.files?.[0]; if (!file) return; const result = await adminRepository.uploadRedComercialProspectFile(current.id, file); if (result.error) setError(result.error); else await refresh(result.data) }
  async function downloadFile(path: string) { const result = await adminRepository.createRedComercialProspectFileSignedUrl(path); if (result.data) window.open(result.data, '_blank', 'noopener,noreferrer'); else setError(result.error ?? 'No fue posible abrir el archivo.') }

  return <aside className="min-h-[640px] min-w-0 w-full rounded-lg border border-[#ddd6ca] bg-white shadow-[0_6px_20px_rgba(23,32,45,0.06)] xl:fixed xl:right-0 xl:top-[var(--admin-topbar-height)] xl:bottom-0 xl:z-40 xl:h-[calc(100vh-var(--admin-topbar-height))] xl:min-h-0 xl:min-w-[390px] xl:w-[var(--detail-panel-width)] xl:overflow-y-auto">
    <div className="sticky top-0 z-10 border-b border-[#eee8dd] bg-white px-3 py-2.5"><div className="flex items-start gap-2.5"><CompanyLogo company={{ name: current.company_name, logo_storage_path: current.logo_storage_path }} size="sm" /><div className="min-w-0 flex-1"><p className="truncate text-[15px] font-semibold text-[#17202d]">{current.company_name}</p><p className="mt-0.5 text-[10px] font-semibold uppercase tracking-[0.12em] text-slate-500">Empresa prospecto</p></div><button type="button" className="rounded border border-[#c9c1b4] p-1.5 text-[#17202d]" aria-label="Cerrar panel" onClick={onClose}><X size={15} /></button></div><div className="mt-2 flex items-center gap-1.5"><select aria-label="Estado del prospecto" value={current.status} onChange={(event) => void changeStatus(event.target.value as RedComercialProspectStatus)} className={`rounded-full border-0 px-2 py-1 text-[11px] font-semibold outline-none ${statusTone[current.status] ?? 'bg-slate-100 text-slate-700'}`}>{statuses.map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select>{current.can_view_detail && onEdit && <button type="button" onClick={onEdit} className="rounded border border-[#c9c1b4] px-2 py-1 text-[11px] font-semibold">Editar</button>}{current.can_view_detail && onActivity && <button type="button" onClick={onActivity} className="rounded bg-[#235b3e] px-2 py-1 text-[11px] font-semibold text-white">+ Actividad</button>}{current.can_view_detail && onSchedule && <button type="button" onClick={onSchedule} className="rounded border border-[#c9c1b4] px-2 py-1 text-[11px] font-semibold">Reprogramar</button>}{current.can_view_detail && onArchive && <button type="button" onClick={onArchive} className="rounded border border-[#c9c1b4] p-1" aria-label={current.is_archived ? 'Restaurar prospecto' : 'Archivar prospecto'}><Archive size={13} /></button>}<button type="button" className="ml-auto rounded border border-[#c9c1b4] p-1" aria-label="Mas acciones"><MoreHorizontal size={14} /></button></div><div className="mt-2 grid grid-cols-4 border-b border-[#eee8dd] text-[11px]">{(['summary', 'activities', 'files', 'notes'] as const).map((item) => <button key={item} type="button" onClick={() => setTab(item)} className={`px-1 py-2 font-semibold ${tab === item ? 'border-b-2 border-[#235b3e] text-[#235b3e]' : 'text-slate-500'}`}>{item === 'summary' ? 'Resumen' : item === 'activities' ? 'Actividades' : item === 'files' ? 'Archivos' : 'Notas'}</button>)}</div></div>
    <div className="px-3 pb-5 text-[12px]">{error && <p className="mt-2 rounded bg-rose-50 px-2.5 py-2 text-rose-800">{error}</p>}{loading ? <p className="py-5 text-slate-500">Cargando panel...</p> : !current.can_view_detail ? <div className="py-5 text-slate-600">Este prospecto esta siendo gestionado por otro colaborador.<br />Responsable: {person(current.owner?.full_name)}</div> : <>
       {tab === 'summary' && <><PanelSection title="Informacion general" action={onEdit && <button type="button" onClick={onEdit} className="text-[11px] font-semibold text-[#235b3e]">Editar</button>}><div>{[['Empresa', current.company_name], ['Contacto', current.contact_name], ['Cargo / area', current.contact_role], ['Email', current.contact_email], ['Telefono', current.contact_phone], ['Canal', current.channel], ['Responsable', current.owner?.full_name ? person(current.owner.full_name) : null], ['Coasignados', current.collaborators.map((item) => person(item.full_name)).join(', ')], ['Fecha primer contacto', date(current.first_contact_at)], ['Ultimo contacto', date(current.last_contact_at)], ['Proximo seguimiento', date(current.next_followup_at)]].map(([label, value]) => <div key={label} className="grid min-h-[32px] grid-cols-[118px_minmax(0,1fr)] items-center gap-2 border-b border-[#f1ece3]"><span className="text-[10.5px] font-semibold text-slate-500">{label}</span><span className={value ? 'text-[#17202d]' : 'text-slate-400'}>{value || 'Sin definir'}</span></div>)}</div></PanelSection><PanelSection title="Estado de la venta" action={opportunity ? <button type="button" onClick={() => openOpportunity(opportunity.id)} className="text-[11px] font-semibold text-[#235b3e]">Abrir oportunidad</button> : !error && canCreateOpportunity ? <button type="button" onClick={() => setOpportunityModal(true)} className="inline-flex items-center gap-1 text-[11px] font-semibold text-[#235b3e]"><Plus size={13} />Crear oportunidad</button> : null}>{!opportunity ? error ? <p className="text-slate-500">No fue posible cargar el estado de la venta.</p> : <p className="text-slate-500">Aun no existe una oportunidad comercial.</p> : <><div className="mb-2 flex items-center justify-between"><StatusBadge status={opportunity.result_status} /><span className="text-[11px] text-slate-500">{opportunity.control_mode === 'arista' ? 'Gestion entregada a Arista' : opportunity.control_mode === 'shared' ? 'Gestion compartida' : 'Gestion colaborador'}</span></div><OpportunityEditor opportunity={opportunity} collaborators={collaborators} services={services} onOpenPlaybook={() => { const service = services.find((item) => item.id === opportunity.represented_company_service_id); if (service) setPlaybookService(service) }} onChange={updateOpportunity} /></>}</PanelSection><PanelSection title="Oportunidad cruzada" action={<button type="button" onClick={() => { setCrossModal(true); void loadCompanies() }} className="inline-flex items-center gap-1 text-[11px] font-semibold text-[#235b3e]"><Plus size={13} />Agregar</button>}><p className="mb-2 text-[11px] text-slate-500">Ves potencial para otra empresa de Arista?</p>{panel?.cross_opportunities.map((item) => <div key={item.id} className="mb-1.5 flex items-start gap-2 rounded bg-[#fbfaf7] px-2.5 py-2"><CompanyLogo company={{ name: item.target_company_name, logo_storage_path: item.target_company_logo_storage_path }} size="xs" /><div className="min-w-0"><p className="font-semibold text-[#17202d]">{item.target_company_name}</p><p className="text-[11px] text-slate-600">{item.reason}</p><span className="text-[10px] text-slate-500">{labelForStatus(item.status)}</span></div></div>)}</PanelSection></>}
      {tab === 'activities' && <PanelSection title="Actividad" action={onActivity && <button type="button" onClick={onActivity} className="text-[11px] font-semibold text-[#235b3e]">+ Registrar</button>}><div className="grid gap-2">{current.activities.length ? current.activities.map((activity) => <div key={activity.id} className="border-l-2 border-[#c9dfd0] pl-2.5"><p className="text-[10px] text-slate-500">{date(activity.activity_at)} - {person(activity.created_by_name)}</p><p className="font-semibold text-[#17202d]">{activity.title}</p>{activity.description && <p className="text-[11px] text-slate-600">{activity.description}</p>}</div>) : <p className="text-slate-500">Sin actividad registrada.</p>}</div></PanelSection>}
      {tab === 'files' && <PanelSection title="Archivos" action={<label className="inline-flex cursor-pointer items-center gap-1 text-[11px] font-semibold text-[#235b3e]"><Upload size={13} />Subir<input type="file" className="hidden" onChange={(event) => void uploadFile(event)} /></label>}><div className="grid gap-1.5">{panel?.files.length ? panel.files.map((file) => <div key={file.id} className="flex items-center gap-2 rounded bg-[#fbfaf7] px-2.5 py-2"><FileText size={15} className="shrink-0 text-[#235b3e]" /><span className="min-w-0 flex-1 truncate"><strong className="block text-[11px] text-[#17202d]">{file.file_name}</strong><small className="text-[10px] text-slate-500">{Math.round(file.size_bytes / 1024)} KB - {file.category}</small></span><button type="button" onClick={() => void downloadFile(file.storage_path)} aria-label={`Abrir ${file.file_name}`} className="rounded p-1 text-[#235b3e]"><Download size={14} /></button><Archive size={14} className="text-slate-400" /></div>) : <p className="text-slate-500">No hay archivos.</p>}</div></PanelSection>}
      {tab === 'notes' && <PanelSection title="Notas" action={<button type="button" onClick={() => setNoteModal(true)} className="inline-flex items-center gap-1 text-[11px] font-semibold text-[#235b3e]"><Plus size={13} />Nueva nota</button>}><div className="grid gap-2">{panel?.notes.length ? panel.notes.map((note) => <div key={note.id} className="rounded bg-[#fbfaf7] px-2.5 py-2"><p className="text-[10px] text-slate-500">{date(note.created_at)}</p><p className="mt-1 whitespace-pre-wrap text-[12px] text-[#17202d]">{note.body}</p></div>) : current.internal_notes ? <div className="rounded bg-[#fbfaf7] px-2.5 py-2"><p className="text-[10px] text-slate-500">Nota legacy</p><p className="mt-1 whitespace-pre-wrap text-[12px] text-[#17202d]">{current.internal_notes}</p></div> : <p className="text-slate-500">Sin notas.</p>}</div></PanelSection>}
    </>}</div>
    {opportunityModal && <NewOpportunityModal prospectId={current.id} collaborators={collaborators} services={services} isAdmin={admin} onClose={() => setOpportunityModal(false)} onSaved={(data) => { void refresh(data); const createdOpportunity = data.opportunities?.[0]; if (createdOpportunity) openOpportunity(createdOpportunity.id) }} />}
    {playbookService && <ServicePlaybookModal service={playbookService} onClose={() => setPlaybookService(null)} />}
    {crossModal && <CrossOpportunityModal prospectId={current.id} companies={companies} currentCompanyId={current.represented_company_id} onClose={() => setCrossModal(false)} onSaved={(data) => void refresh(data)} />}
    {noteModal && <AdminDetailModal title="Nueva nota" onClose={() => setNoteModal(false)}><form className="grid gap-3" onSubmit={(event) => void submitNote(event)}><textarea name="body" rows={5} required className="rounded border border-[#c9c1b4] px-3 py-2" placeholder="Escribe una nota interna..." /><div className="flex justify-end gap-2"><button type="button" onClick={() => setNoteModal(false)} className="rounded border border-[#c9c1b4] px-3 py-2 font-semibold">Cancelar</button><button className="rounded bg-[#235b3e] px-3 py-2 font-semibold text-white">Guardar nota</button></div></form></AdminDetailModal>}
  </aside>
}
